#!/usr/bin/env python3
"""Clip instructions from the dataset label, objects, hands, measured motion and render frames, generated by the
Claude Messages API (CPU, standard library only — REST without the SDK).

Unit = one source clip (or segment), independent of hand, placement variant and look: every episode of a clip
shares one text. Sub-commands:
  build    input records (records.jsonl, built by sources) -> requests.jsonl, manifest.json, cost estimate
  estimate cost per model (batch and synchronous); prices owned by api.PRICES
  run      synchronous calls (--limit, --workers, --usd-cap) -> raw.jsonl
  submit   batch API (50 % off, within 24 h), split per 100,000 requests / 256 MB -> batches.json
  status   batch progress
  fetch    ended batches -> raw.jsonl (by custom_id; rows already received are skipped)
  validate raw.jsonl -> texts.jsonl (passed) + rejects.jsonl (reasons) + summary; requests = passed + rejected + missing
  show     one clip's request and response (for review)
  redo     rejections ∪ confidence REDO_CONFIDENCE of one folder -> a new folder for another model
  merge    several folders (oldest first) -> one final table (a later folder's passed row wins; clips that never pass
           go to merge_rejects.jsonl) — the table the store reads (DEXENGINE_COLLECT_TEXTS)
  retext   load the final table into stored datasets (store.tasks.retext; --texts or --off explicitly)
  track    one pass of the idempotent text pipeline (pipeline.py)
Layers: transport, prices and estimate = api; output contract (schema, checks) = check; one clip's request = request;
store hook and retext = text_table; this module = request folders, CLI, merge. Key from env ANTHROPIC_API_KEY (never
printed). The model is always given with --model (no default). Marker: [COLLECT_TEXT] <sub-command> ...; failures
exit != 0.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
import time
from pathlib import Path

from dexengine.core.repo import CONFIGS_DIR
from dexengine.record.phases import full_table
from dexengine.record.text import api as CTA
from dexengine.record.text import rules_scene as RULES
from dexengine.record.text.api import MARK, PRICES, die, estimate, read_jsonl, write_jsonl
from dexengine.record.text.check import SCHEMA, normalize, output, validate_one
from dexengine.record.text.nouns import object_vocab
from dexengine.record.text.request import request_params
from dexengine.record.text.text_table import cmd_retext

#: Prompt files (model inputs: system.md, datasets.json). Every file in this folder enters prompt_sha, so the folder
#: holds only these two.
PROMPT_DIR = CONFIGS_DIR / "record" / "text"


# ───────────────────────── request building ─────────────────────────
def prompt_files() -> tuple[str, dict]:
    """(filled system prompt, filled per-dataset notes)."""
    system = RULES.fill_prompt((PROMPT_DIR / "system.md").read_text(encoding="utf-8"))
    ds = json.loads(RULES.fill_prompt((PROMPT_DIR / "datasets.json").read_text(encoding="utf-8")))
    return system, ds


def prompt_sha() -> str:
    """Fingerprint of everything that shapes the request: the prompt files, the schema and the filled system
    prompt."""
    h = hashlib.sha256()
    for f in sorted(PROMPT_DIR.glob("*")):
        h.update(f.name.encode() + b"\0" + f.read_bytes())
    h.update(json.dumps(SCHEMA, sort_keys=True).encode() + prompt_files()[0].encode())
    return h.hexdigest()[:12]


def custom_id(rec: dict) -> str:
    """Fixed id per clip / segment (batch custom_id is at most 64 characters); same input, same id."""
    key = f"{rec['dataset']}/{rec['clip']}"
    return hashlib.sha256(key.encode()).hexdigest()[:24]


def cmd_build(a) -> int:
    """build: records -> request folder (--skip drops clips already in a final table)."""
    recs = read_jsonl(Path(a.records))
    if not recs:
        die(f"no input records in {a.records}")
    if a.skip:
        done = {r["clip"] for f in a.skip for r in read_jsonl(Path(f))}
        new = [r for r in recs if r["clip"] not in done]
        print(
            f"{MARK} build targets {len(recs)} = new {len(new)} + already received {len(recs) - len(new)}", flush=True
        )
        if not new:
            print(f"{MARK} build no new clips — no folder made", flush=True)
            return 0
        recs = new
    return build_dir(recs, Path(a.out), a.model)


def build_dir(recs: list[dict], out: Path, model: str, extra: dict | None = None) -> int:
    """Write requests.jsonl, records.jsonl (phase table filled to the five PHASES), manifest.json and estimate.json."""
    if model not in PRICES:
        die(f"unknown model {model!r}: only those in PRICES ({', '.join(PRICES)})")
    system, ds = prompt_files()
    out.mkdir(parents=True, exist_ok=True)
    recs = [dict(r, phases=full_table(r.get("phases") or [])) for r in recs]
    reqs, seen = [], {}
    for r in recs:
        cid = custom_id(r)
        if cid in seen:
            die(f"same clip twice: {r['dataset']}/{r['clip']}")
        seen[cid] = r
        q = {"custom_id": cid, "params": request_params(r, model, system, ds)}
        if r.get("frames"):
            q["frames"] = [{k: f.get(k) for k in ("view", "t_s", "w", "h", "phase", "at")} for f in r["frames"]]
        reqs.append(q)
    write_jsonl(out / "requests.jsonl", reqs)
    write_jsonl(out / "records.jsonl", recs)
    man = dict(
        model=model,
        n=len(reqs),
        prompt_sha=prompt_sha(),
        prompt_gen=RULES.PROMPT_GEN,
        built=time.strftime("%Y-%m-%dT%H:%M:%S"),
        by_dataset={d: sum(1 for r in recs if r["dataset"] == d) for d in sorted({r["dataset"] for r in recs})},
        **(extra or {}),
    )
    (out / "manifest.json").write_text(json.dumps(man, ensure_ascii=False, indent=1), encoding="utf-8")
    est = estimate(reqs)
    (out / "estimate.json").write_text(json.dumps(est, indent=1), encoding="utf-8")
    print(f"{MARK} build n={len(reqs)} model={model} prompt={man['prompt_sha']} → {out}", flush=True)
    print_estimate(est)
    return 0


def print_estimate(est: dict) -> None:
    """Print a cost estimate (api.estimate)."""
    if not est:
        return
    print(
        f"{MARK} estimate n={est['n']} system ≈{est['sys_tokens']} tokens · input mean ≈{est['user_tokens_mean']}"
        f" (images {est.get('image_tokens_mean', 0)} · {est.get('images', 0)} images) · "
        f"output assumed {est['out_tokens_assumed']}",
        flush=True,
    )
    for m, v in est["models"].items():
        print(
            f"  {m:20s} batch ${v['batch_usd']:.2f} (no cache ${v['batch_usd_no_cache']:.2f}) · "
            f"sync ${v['sync_usd']:.2f}",
            flush=True,
        )


def cmd_estimate(a) -> int:
    """estimate: cost of a request folder."""
    reqs = read_jsonl(Path(a.dir) / "requests.jsonl")
    print_estimate(estimate(reqs))
    return 0


def cmd_validate(a) -> int:
    """validate: raw.jsonl -> texts.jsonl + rejects.jsonl + summary.json (count check)."""
    d = Path(a.dir)
    recs = {custom_id(r): r for r in read_jsonl(d / "records.jsonl")}
    raw = {r["custom_id"]: r for r in read_jsonl(d / "raw.jsonl")}
    man = json.loads((d / "manifest.json").read_text())
    # object vocabulary = records of this round and its sibling rounds (all datasets, rebuilt every time)
    vocab = object_vocab(
        r for f in sorted({d / "records.jsonl", *d.parent.glob("*/records.jsonl")}) for r in read_jsonl(f)
    )
    ok_rows, rej, usage = (
        [],
        [],
        {"input_tokens": 0, "output_tokens": 0, "cache_read_input_tokens": 0, "cache_creation_input_tokens": 0},
    )
    for cid, rec in recs.items():
        r = raw.get(cid)
        if r is None:
            continue
        res = r["result"]
        if res["type"] != "succeeded":
            rej.append(
                {"custom_id": cid, "clip": rec["clip"], "dataset": rec["dataset"], "why": [f"result {res['type']}"]}
            )
            continue
        for k in usage:
            usage[k] += int((res["message"].get("usage") or {}).get(k) or 0)
        out = output(res["message"])
        out = None if out is None else normalize(out)
        why = ["no output (not JSON · refused · truncated)"] if out is None else validate_one(rec, out, vocab)
        row = dict(
            custom_id=cid,
            dataset=rec["dataset"],
            clip=rec["clip"],
            segment=rec.get("segment"),
            model=man["model"],
            prompt_sha=man["prompt_sha"],
            prompt_gen=man.get("prompt_gen", 0),
            **(out or {}),
        )
        (rej if why else ok_rows).append({**row, "why": why} if why else row)
    write_jsonl(d / "texts.jsonl", ok_rows)
    write_jsonl(d / "rejects.jsonl", rej)
    n, got = len(recs), len(ok_rows) + len(rej)
    summ = {
        "requests": n,
        "passed": len(ok_rows),
        "rejected": len(rej),
        "missing": n - got,
        "usage": usage,
        "by_confidence": {c: sum(1 for r in ok_rows if r["confidence"] == c) for c in ("high", "medium", "low")},
    }
    (d / "summary.json").write_text(json.dumps(summ, ensure_ascii=False, indent=1))
    print(
        f"{MARK} validate requests {n} = passed {len(ok_rows)} + rejected {len(rej)} + missing {n - got} · "
        f"confidence {summ['by_confidence']} · usage {usage}",
        flush=True,
    )
    if len(ok_rows) + len(rej) + (n - got) != n:
        die("count mismatch")
    return 0


# ───────────────────────── redo · merge · retext ─────────────────────────
#: Confidence levels that are regenerated along with the rejections (medium is not).
REDO_CONFIDENCE = ("low",)


def cmd_redo(a) -> int:
    """redo: rejections ∪ REDO_CONFIDENCE rows of a validated folder -> a new request folder (--with-why adds the
    retry reasons)."""
    src = Path(a.src)
    if not (src / "summary.json").is_file():
        die(f"{src} has no validate result (summary.json): redo runs after validate")
    recs = {custom_id(r): r for r in read_jsonl(src / "records.jsonl")}
    rej = {r["custom_id"] for r in read_jsonl(src / "rejects.jsonl")}
    low = {r["custom_id"] for r in read_jsonl(src / "texts.jsonl") if r["confidence"] in REDO_CONFIDENCE}
    from dexengine.record.text import retry as RT

    why = RT.for_redo(src) if a.with_why else {}
    pick = [dict(recs[c], retry_why=why[c]) if c in why else recs[c] for c in recs if c in rej | low]
    print(
        f"{MARK} redo {src.name}: rejected {len(rej)} + confidence {'/'.join(REDO_CONFIDENCE)} {len(low)} → "
        f"{len(pick)} → {a.model}",
        flush=True,
    )
    if not pick:
        print(f"{MARK} redo nothing to redo — no folder made", flush=True)
        return 0
    return build_dir(
        pick,
        Path(a.out),
        a.model,
        extra={"redo_from": str(src), "redo_rejects": len(rej), "redo_low": len(low), "redo_with_why": bool(why)},
    )


def cmd_merge(a) -> int:
    """merge: folders oldest first, the last passed row per clip wins; count check (union = passed + unresolved).
    Rows outside a.pairs (a (dataset, clip) list file, when given) stay out of the table and are counted."""
    tg = {tuple(x.split("\t")[:2]) for x in Path(a.pairs).read_text().splitlines() if x.strip()} if a.pairs else None
    best, last_rej, order, stray = {}, {}, [], set()
    for d in map(Path, a.dir):
        if not (d / "summary.json").is_file():
            die(f"{d} has no validate result (summary.json)")
        for f, keep in (("rejects.jsonl", False), ("texts.jsonl", True)):
            for r in read_jsonl(d / f):
                if tg is not None and (r["dataset"], r["clip"]) not in tg:
                    stray.add((r["dataset"], r["clip"]))
                    continue
                if keep:
                    best[r["clip"]] = r
                else:
                    last_rej[r["clip"]] = {**r, "dir": str(d)}
                order.append(r["clip"])
    if stray:
        print(f"{MARK} merge {len(stray)} rows outside the targets left out {sorted(stray)[:5]}", flush=True)
    clips = list(dict.fromkeys(order))
    rows = [best[c] for c in clips if c in best]
    unresolved = [last_rej[c] for c in clips if c not in best]
    out = Path(a.out)
    out.parent.mkdir(parents=True, exist_ok=True)
    write_jsonl(out, rows)
    write_jsonl(out.parent / "merge_rejects.jsonl", unresolved)
    summ = {
        "dirs": a.dir,
        "clips": len(clips),
        "passed": len(rows),
        "unresolved": len(unresolved),
        "by_model": {m: sum(1 for r in rows if r["model"] == m) for m in sorted({r["model"] for r in rows})},
        "by_confidence": {c: sum(1 for r in rows if r["confidence"] == c) for c in ("high", "medium", "low")},
        "prompt_sha": sorted({r["prompt_sha"] for r in rows}),
    }
    (out.parent / "merge_summary.json").write_text(json.dumps(summ, ensure_ascii=False, indent=1))
    print(
        f"{MARK} merge folders {len(a.dir)} · clips {len(clips)} = passed {len(rows)} + unresolved "
        f"{len(unresolved)} · models {summ['by_model']} · confidence {summ['by_confidence']} → {out}",
        flush=True,
    )
    if len(rows) + len(unresolved) != len(clips):
        die("count mismatch")
    return 0


def cmd_show(a) -> int:
    """show: print the first record whose clip name contains --match, its request text and response."""
    d = Path(a.dir)
    recs = read_jsonl(d / "records.jsonl")
    hit = [r for r in recs if a.match in r["clip"]]
    if not hit:
        die(f"no record whose clip name contains {a.match!r}")
    r = hit[0]
    req = {q["custom_id"]: q for q in read_jsonl(d / "requests.jsonl")}.get(custom_id(r))
    print(json.dumps(r, ensure_ascii=False, indent=1))
    if req:
        c = req["params"]["messages"][0]["content"]
        if isinstance(c, list):
            fr = req.get("frames", [])
            print("── frames ──\n" + "\n".join(f"{f['view']} t={f['t_s']} {f['w']}×{f['h']}" for f in fr))
            c = c[-1]["text"]
        print("── user ──\n" + c)
    res = {x["custom_id"]: x for x in read_jsonl(d / "raw.jsonl")}.get(custom_id(r))
    if res and res["result"]["type"] == "succeeded":
        print("── response ──\n" + json.dumps(output(res["result"]["message"]), ensure_ascii=False, indent=1))
    return 0


def main(argv=None) -> int:
    """CLI of the text sub-commands (see the module docstring)."""
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sp = ap.add_subparsers(dest="cmd", required=True)
    b = sp.add_parser("build")
    b.add_argument("--records", required=True)
    b.add_argument("--out", required=True)
    b.add_argument("--model", required=True)
    b.add_argument(
        "--skip",
        action="append",
        default=[],
        help="tables already received (final texts.jsonl): their clips are left out",
    )
    rd = sp.add_parser("redo")
    rd.add_argument("--from", dest="src", required=True, help="a validated folder")
    rd.add_argument("--model", required=True)
    rd.add_argument("--out", required=True)
    rd.add_argument("--with-why", action="store_true", help="put the rejection reasons into the request (retry_why)")
    mg = sp.add_parser("merge")
    mg.add_argument("--dir", action="append", required=True, help="folder (repeat, oldest first)")
    mg.add_argument("--out", required=True, help="final table (texts.jsonl)")
    mg.add_argument("--pairs", default=None, help="target (dataset, clip) list: other rows stay out of the table")
    rt = sp.add_parser("retext")
    rt.add_argument("--dataset", action="append", required=True)
    g = rt.add_mutually_exclusive_group(required=True)
    g.add_argument("--texts", help="final table")
    g.add_argument("--off", action="store_true", help="back to the source labels")
    for name in ("estimate", "status", "fetch", "validate"):
        sp.add_parser(name).add_argument("--dir", required=True)
    r = sp.add_parser("run")
    r.add_argument("--dir", required=True)
    r.add_argument("--limit", type=int, required=True)
    r.add_argument("--workers", type=int, default=1, help="concurrent requests")
    r.add_argument("--usd-cap", type=float, default=None, help="cost cap of this run ($)")
    s = sp.add_parser("submit")
    s.add_argument("--dir", required=True)
    s.add_argument("--force", action="store_true")
    from dexengine.record.text import pipeline as CTT  # lazy: pipeline imports this module

    CTT.track_args(sp.add_parser("track", help="one pass of the text pipeline (pipeline.py; config <root>/track.json)"))
    sh = sp.add_parser("show")
    sh.add_argument("--dir", required=True)
    sh.add_argument("--match", required=True, help="part of a clip name (the first matching record is printed)")
    a = ap.parse_args(argv)
    if a.cmd == "track":
        return CTT.run_track(a)
    return {
        "build": cmd_build,
        "estimate": cmd_estimate,
        "run": CTA.cmd_run,
        "submit": CTA.cmd_submit,
        "status": CTA.cmd_status,
        "fetch": CTA.cmd_fetch,
        "validate": cmd_validate,
        "show": cmd_show,
        "redo": cmd_redo,
        "merge": cmd_merge,
        "retext": cmd_retext,
    }[a.cmd](a)


if __name__ == "__main__":
    sys.exit(main())
